/**
 * Hand-written database row types.
 * These are not generated by the Supabase CLI.
 * Replace them later with `supabase gen types typescript` when a real project is linked.
 */

export type ContentStatus = "draft" | "published";

export type Category = {
  id: string;
  name: string;
  slug: string;
  created_at: string;
};

export type Post = {
  id: string;
  title: string;
  slug: string;
  excerpt: string | null;
  content: string;
  /** Path inside the blog-covers bucket, or a legacy absolute URL. */
  cover_image: string | null;
  category_id: string | null;
  tags: string[];
  status: ContentStatus;
  published_at: string | null;
  created_at: string;
  updated_at: string;
};

export type PostSummary = Pick<
  Post,
  "id" | "title" | "slug" | "excerpt" | "cover_image" | "category_id" | "tags" | "published_at"
>;

export type Project = {
  id: string;
  title: string;
  slug: string;
  description: string;
  content: string | null;
  cover_image: string | null;
  technologies: string[];
  github_url: string | null;
  live_url: string | null;
  featured: boolean;
  status: ContentStatus;
  published_at: string | null;
  created_at: string;
  updated_at: string;
};

export type ProjectSummary = Pick<
  Project,
  | "id"
  | "title"
  | "slug"
  | "description"
  | "cover_image"
  | "technologies"
  | "github_url"
  | "live_url"
  | "featured"
  | "published_at"
>;
